 function filing(st,ids){if(mediaMode(st)&&['Publication photographs','Photographs'].includes(mediaCatalog.label))return `<div class="wfb-bulk"><span>${ids.length} selected</span>${button('Clear','selectionclear')}</div>`;if(st.nativeOwner&&st.folder==='native')return `<div class="wfb-bulk"><span>${ids.length} selected</span>${button('Clear','selectionclear')}<span>Open a photograph to edit its saved selection and details.</span></div>`;return `<div class="wfb-bulk" role="toolbar" aria-label="File selection"><span>${ids.length} selected</span>${button('Link to folder','link',st.busy||(catalogMode(st)||mediaMode(st))&&st.data?.readOnly?'disabled title="'+(st.data?.readOnly?'Folders are read-only in this view':'Reading folders…')+'"':'')}${button('Move to folder','move',st.busy||(catalogMode(st)||mediaMode(st))&&st.data?.readOnly?'disabled title="'+(st.data?.readOnly?'Folders are read-only in this view':'Reading folders…')+'"':'')}${st.data?.folders.some(f=>f.id===st.folder)?button('Unlink here','unlink',st.busy?'disabled':''):''}${button('Tag','unavailable','disabled title="Topic tagging is not connected to this browser"')}${button('Add to piece','unavailable','disabled title="Choose media from the piece’s Arrange photo picker"')}${button('Clear','selectionclear')}</div>`;}
 function previewHTML(st){const s=st.data?.sources.find(s=>s.id===st.preview);if(!s)return `<p role="status">This source is unavailable. ${button('Back to list','back')}</p>`;const k=kind(s),url=safePhotoURL(st,s),folders=(st.data?.folders||[]).filter(f=>f.sourceIds.includes(s.id)),media=['image','video','audio'].includes(k);const content=unavailable(s)?'<p>The original is unavailable. Its saved folder links are kept.</p>':k==='image'&&!url?'<p>Preview unavailable. Its saved details remain here.</p>':k==='image'?`<div class="wfb-mpv"><img src="${esc(url)}" alt="${esc(title(s))}"></div>`:k==='video'||k==='audio'?actualWork?'<p>Preview unavailable in this read-only review.</p>':`<${k} src="${esc(blobURL(s))}" controls preload="metadata"></${k}>`:st.previewError?`<p role="status">${esc(friendly(st.previewError,'This source could not open. Try again.'))}</p>`:st.previewText===null?'<p role="status">Reading source…</p>':`<pre class="wfb-reading">${esc(st.previewText||'No readable text is available for this source.')}</pre>`;if(st.domain==='library')return `<div class="wfb-preview"><div class="wfb-library-detail"><dl class="wfb-library-kv"><dt>Source</dt><dd>${esc(s.publication||s.channel||'Not recorded')}</dd><dt>Date</dt><dd>${esc(date(s)?fmtDate(date(s)):'Not recorded')}</dd></dl><details class="wfb-original-file"><summary>Original file</summary><p>${esc((s.rel_path||'').split('/').pop()||title(s))}</p><dl><dt>Source ID</dt><dd>${esc(s.id)}</dd></dl></details><h3 class="wfb-library-kind">${esc(kindLabel(k))}</h3>${content}${filing(st,[s.id])}${collectionsHTML(s.id)}<h3>In ${folders.length} folder${folders.length===1?'':'s'}</h3><ul class="wfb-memberships">${folders.map(f=>`<li><button type="button" data-wfb-folder-pick="${esc(f.id)}">${esc(folderPath(st,f.id).map(f=>f.name).join(' › '))}</button><button type="button" data-wfb-unlink="${esc(f.id)}">Unlink</button></li>`).join('')||'<li>Unsorted — in no folder yet.</li>'}</ul></div></div>`;return `<div class="wfb-preview">${st.domain==='library'?'':`<div class="wfb-preview-back">${button('Back to list','back')}<span>${esc(kindLabel(k))}${unavailable(s)?' · Original unavailable':''}</span></div>`}<div class="wfb-detail-grid${media?' has-media':''}"><div class="wfb-detail-content">${content}</div><div class="wfb-detail-meta">${['magazine-publication','magazine-library'].includes(s.previewKind)?`<h2>${esc(title(s))}</h2><details><summary>File details</summary><p>${esc((s.rel_path||'').split('/').pop())}</p></details>`:`<dl><dt>File</dt><dd>${esc((s.rel_path||'').split('/').pop()||title(s))}</dd><dt>Kind</dt><dd>${esc(kindLabel(k))}</dd><dt>Date</dt><dd>${esc(date(s)?fmtDate(date(s)):'Not recorded')}</dd></dl>${filing(st,[s.id])}<h3>In folders</h3>`}<ul class="wfb-memberships">${['magazine-publication','magazine-library'].includes(s.previewKind)?'':folders.map(f=>`<li><button type="button" data-wfb-folder-pick="${esc(f.id)}">${esc(folderPath(st,f.id).map(f=>f.name).join(' › '))}</button><button type="button" data-wfb-unlink="${esc(f.id)}">Unlink</button></li>`).join('')||'<li>Unsorted</li>'}</ul>${st.domain==='media'?`<section class="wfb-usages" data-wfb-usage-detail="${esc(s.id)}">${usageDetail(st,s.id)}</section>${mediaMode(st)?'':button('This piece · captions, credits and usage','native')}`:''}</div></div></div>`;}
 function sortButton(st,key,label){return `<button type="button" data-wfb-order="${key}" ${st.sort===key?`aria-sort="${st.direction<0?'descending':'ascending'}"`:''}>${label}${st.sort===key?(st.direction<0?' ↓':' ↑'):''}</button>`;}
 const libraryColumnCache=new WeakMap();
 const readingLabel=s=>({read:'Read',reading:'Reading',unread:'To read','to-read':'To read'})[s.readingStatus]||(typeof s.readingStatus==='string'&&!/^(?:unknown|unavailable|—)$/i.test(s.readingStatus.trim())?s.readingStatus.trim():'');
 function libraryColumns(st){if(catalogMode(st)&&st.data&&libraryColumnCache.has(st.data))return libraryColumnCache.get(st.data);const sources=st.data?.sources||[],columns={used:sources.some(s=>typeof s.usedInPiece==='boolean'),status:sources.some(s=>!!readingLabel(s)),origin:sources.some(s=>!!(s.publication||s.channel))};if(catalogMode(st)&&st.data)libraryColumnCache.set(st.data,columns);return columns;}
 function listHead(st,rows){const columns=libraryColumns(st),checkbox=`<input type="checkbox" data-wfb-all aria-label="Select all ${rows.length} matching" ${rows.length&&rows.every(s=>st.selection.has(s.id))?'checked':''}>`;if(st.mode==='grid')return `<div class="wfb-vhead">${checkbox}<span class="wfb-grid-select">Select all ${rows.length.toLocaleString()}</span><span class="wfb-grid-sorts">${sortButton(st,'title','Title')}${sortButton(st,'kind','Kind')}${sortButton(st,'date','Date')}${mediaMode(st)&&['Publication photographs','Photographs'].includes(mediaCatalog.label)?'':'<span>Folder</span><span title="Global Library usage is not connected">Used in</span>'}</span></div>`;return `<div class="wfb-vhead">${checkbox}<span></span>${sortButton(st,'title','Title')}${sortButton(st,st.domain==='library'?'source':'kind',st.domain==='library'?(libraryColumns(st).origin?'Source':'Type'):'Kind')}${sortButton(st,'date','Date').replace('<button','<button class="wfb-date"')}<span class="wfb-folder-column">Folder</span>${st.domain==='media'||columns.used?`<span class="wfb-used-column" title="${st.domain==='media'?'Current project and native root only; global usage is unknown':'Saved piece-use metadata; not a complete global usage scan'}">${st.domain==='media'?'Used in project':'Used in'}</span>`:''}${st.domain==='library'&&columns.status?'<span class="wfb-state-column">Status</span>':''}</div>`;}
 function render(st){if(catalogMode(st)&&!st.data)return `<header class="wfb-thead thead"><div class="wfb-crumbs">Library</div>${button('Folders','folders')}</header><p role="status">${st.catalogError?esc(st.catalogError):'Reading your Library sources…'}</p>${st.catalogError?button('Try again','refresh'):''}${toolbar(st)}`;const rows=items(st);if(mediaMode(st)&&!mediaCatalog.ready&&!mediaCatalog.error&&!st.error)return `<header class="wfb-thead thead"><div class="wfb-crumbs">${esc(mediaCatalog.label||'Media')}</div></header><p role="status">Reading saved photographs…</p>`;if(st.nativeOwner&&st.folder==='native'&&st.preview){const photo=st.nativeSources.find(s=>s.id===st.preview);return `<header class="wfb-thead thead">${button(icon('chev')+'Back','back','class="wfb-back5" title="Back to the list (Esc)"')}<div class="wfb-crumbs"><span>This piece</span><span>›</span><span>${esc(photo?title(photo):'Photograph')}</span></div></header><div class="wfb-native-owner" data-native-owner></div>${st.error?`<p role="alert">${esc(st.error)}</p>`:''}`;}return `<header class="wfb-thead thead">${st.preview&&st.domain==='library'?button(icon('chev')+'Back','back','class="wfb-back5" title="Back to the list (Esc)"'):''}<div class="wfb-crumbs" aria-label="Folder path">${breadcrumb(st)}${st.preview?`<span aria-hidden="true">›</span><span class="wfb-current-title">${esc(title(st.data?.sources.find(s=>s.id===st.preview)||{}))}</span>`:''}</div><span class="wfb-count" aria-label="${!st.data&&!(st.folder==='native'&&(st.picker||st.nativeOwner))?'Source list unavailable':rows.length+' shown of '+pickerSources(st).length} ${st.domain==='library'?'sources':'media'}">${!st.data&&!(st.folder==='native'&&(st.picker||st.nativeOwner))?'—':rows.length===pickerSources(st).length?rows.length:rows.length+' of '+pickerSources(st).length}</span>${st.picker?'':button('Folders','folders')}</header>${catalogMode(st)&&libraryCatalog&&!libraryCatalog.ready?'<p class="wfb-status" role="status">Saved source list · checking for updates…</p>':''}${collectionHeading(st)}${st.nativeOwner&&st.folder==='native'?'<div class="wfb-native-owner" data-native-owner></div>':''}${folderStatus(st)}${st.busy?'<p class="wfb-status" role="status">Saving folders…</p>':''}${formHTML(st)}${st.preview?previewHTML(st):`${toolbar(st)}${st.selection.size?(st.picker?`<div class="wfb-bulk"><span>${st.selection.size} selected</span>${st.onPickMany?button('Fill '+Math.min(st.selection.size,st.maxPick)+' slots in order','fillphotos',st.maxPick<1?'disabled':''):''}${button('Clear','selectionclear')}</div>`:filing(st,[...st.selection])):''}${listHead(st,rows)}<div class="wfb-vt${st.mode==='grid'?' wfb-grid':''}" tabindex="0" role="region" aria-label="${LABEL[st.domain]} source list"><div class="wfb-vt-sp"></div></div>`}`;}

 // Saved usage is a bounded read-only projection of the current native root.
 function usageScope(){let p,b,selected;try{p=current();b=window.studyDraft?.currentBinding?.();selected=window.studyOutputConnection?.selection?.();}catch{return null;}const uuid=/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i;if(!p?.id)return null;const root=selected?.projectId===p.id&&uuid.test(selected.rootBindingId||'')?selected.rootBindingId:b?.parentStudyId===p.id&&b.kind!=='output-fork'&&uuid.test(b.id||'')?b.id:null;return root?{parentStudyId:p.id,rootBindingId:root}:null;}
 function usageKey(scope){if(!scope)return '';let proof;try{const p=window.studyOutputConnection?.canvasProof?.();if(p?.scope?.parentStudyId===scope.parentStudyId&&p?.scope?.rootBindingId===scope.rootBindingId)proof=[p.selectedOutputId,!!p.pending,p.browserDraftToken||null];}catch{}return JSON.stringify([scope.parentStudyId,scope.rootBindingId,proof||null]);}
 const usageScopeFor=st=>st.folder==='native'&&(st.picker||st.nativeOwner)?(st.picker?null:st.nativeOwner?.scope||null):usageScope();
 function usageState(st){const scope=usageScopeFor(st),key=usageKey(scope);if(!st.usage||st.usage.key!==key)st.usage={key,scope,records:new Map(),pending:new Set(),error:''};return st.usage;}
 function usageRecord(st,id){return st.domain==='media'?usageState(st).records.get(id):null;}
 function usageLabel(st,id){if(mediaMode(st)){const s=st.data?.sources.find(s=>s.id===id),u=s?.currentArticleUsage;if(u){const label=u.status==='used'?u.count+' in article':u.status==='not-used-in-article'?'Not in article':'Usage unavailable';return {text:label,title:'Current working article only. Other uses are unknown.'};}return {text:s?.placements.length?s.placements.length+' known':'Unknown',title:'Exact saved placements only; total usage is unknown'};}const source=catalogMode(st)?st.data?.sources.find(row=>row.id===id):null;if(typeof source?.usedInPiece==='boolean')return {text:source.usedInPiece?'Used':'Not marked',title:'Saved piece-use metadata; not a complete global usage scan'};if(st.domain!=='media')return {text:'Unknown',title:'Global Library usage is not connected'};const u=usageState(st),r=u.records.get(id);if(!u.scope)return {text:'Unknown',title:'Open an owned working manuscript or output in this project to read saved usage. Global usage is unknown.'};if(!r)return {text:'Unknown',title:u.error||'Saved usage in this project has not been read. Global usage is unknown.'};const n=r.source.occurrences.length,complete=r.coverage.complete===true&&r.source.status==='available';return {text:n?n+(complete?'':'+')+' in project':complete?'0 in project':'Unknown',title:'Saved uses in this project and native root only. '+(!complete?'Coverage is partial or the source is unavailable. ':'')+'Global usage is unknown.'};}
 function usageDetail(st,id){if(mediaMode(st))return mediaDetails(st,st.data.sources.find(s=>s.id===id));const u=usageState(st),r=u.records.get(id);if(!u.scope)return '<h3>Used in this project</h3><p>Choose an owned working manuscript or output in this project to inspect saved placements. Global usage is unknown.</p>';const head='<div class="wfb-usage-heading"><h3>Used in this project</h3><button type="button" data-wfb-usage-refresh aria-label="Refresh saved usage">Refresh</button></div><p class="wfb-usage-scope">Saved Article/Carousel placements in the current project and native root. Global usage is unknown.</p>';if(!r)return head+'<p role="status">'+esc(u.error||(typeof window.studyMediaUsage?.read!=='function'?'Saved placement reader is unavailable. Global usage is unknown.':'Reading saved placements…'))+'</p>';const rows=r.source.occurrences;return head+(u.error?'<p role="status">'+esc(u.error)+'</p>':'')+(!r.coverage.complete||r.source.status!=='available'?'<p>Coverage is partial or unavailable. Other uses may exist.</p>':'')+(rows.length?'<ul>'+rows.map(o=>{const l=o.location,label=o.kind==='carousel'?'Slide '+l.slideNumber+' · photo '+(l.photoNumber??l.photoIndex+1):'Article · '+(l.slot||l.section||'saved placement');return '<li><div><strong>'+esc(o.outputName||'Saved output')+'</strong><span>'+esc(label)+'</span>'+(o.caption?'<p>Caption: '+esc(o.caption)+'</p>':'')+(o.credit?'<p>Credit: '+esc(o.credit)+'</p>':'')+'</div><button type="button" data-wfb-usage-open="'+esc(o.id)+'" data-wfb-usage-source="'+esc(id)+'">Open</button></li>';}).join('')+'</ul>':'<p>'+(r.coverage.complete&&r.source.status==='available'?'No saved placements in this project and native root.':'No known placements in the supported outputs; other uses remain unknown.')+'</p>');}
 function paintUsage(st){if(!st.node?.isConnected)return;for(const node of st.node.querySelectorAll('[data-wfb-usage]')){const label=usageLabel(st,node.dataset.wfbUsage);node.textContent=label.text;node.title=label.title;}const detail=st.node.querySelector('[data-wfb-usage-detail]');if(detail&&detail.dataset.wfbUsageDetail===st.preview)detail.innerHTML=usageDetail(st,st.preview);}
 function ensureUsage(st,ids){if(mediaMode(st)||st.domain!=='media'||st.disposed||!st.node?.isConnected)return;const u=usageState(st);if(!u.scope||typeof window.studyMediaUsage?.read!=='function')return;const wanted=[...new Set(ids)].filter(id=>!u.records.has(id)&&!u.pending.has(id)).slice(0,200);if(!wanted.length)return;for(const id of wanted)u.pending.add(id);const node=st.node;
 Promise.resolve().then(()=>window.studyMediaUsage.read({...u.scope,sourceIds:wanted})).then(value=>{if(st.usage!==u||usageKey(usageScopeFor(st))!==u.key||st.node!==node||!node.isConnected||st.disposed)return;if(value?.schema!=='ar-create.media-usage.v1'||value.scope?.parentStudyId!==u.scope.parentStudyId||value.scope?.rootBindingId!==u.scope.rootBindingId||!/^[a-f0-9]{64}$/.test(value.usageHash||'')||!value.coverage||!Array.isArray(value.sources)||value.sources.length!==wanted.length||new Set(value.sources.map(row=>row.sourceId)).size!==wanted.length||value.sources.some(row=>!wanted.includes(row.sourceId)||!Array.isArray(row.occurrences)||row.occurrences.some(o=>o.sourceId!==row.sourceId||o.scope?.parentStudyId!==u.scope.parentStudyId||o.scope?.rootBindingId!==u.scope.rootBindingId||typeof o.id!=='string'||!o.location||!['article','carousel'].includes(o.kind))))throw Error('Saved placement evidence did not match this project and source. Refresh to read it again.');for(const row of value.sources)u.records.set(row.sourceId,{source:row,coverage:value.coverage,hash:value.usageHash});u.error='';paintUsage(st);}).catch(error=>{if(st.usage!==u||usageKey(usageScopeFor(st))!==u.key||st.node!==node||!node.isConnected)return;u.error=error.message||'Saved placement evidence is unavailable.';for(const id of wanted)u.records.set(id,{source:{sourceId:id,status:'unavailable',occurrences:[]},coverage:{complete:false},hash:null});paintUsage(st);}).finally(()=>{for(const id of wanted)u.pending.delete(id);});}
